// Deterministic atlas registration/encoding only. Original artwork is generated by image_gen.
import Foundation
import AppKit
import ImageIO
let root=URL(fileURLWithPath:FileManager.default.currentDirectoryPath)
let art=root.appendingPathComponent("assets/pips/pixel")
let fm=FileManager.default
let catalog=try JSONSerialization.jsonObject(with:Data(contentsOf:art.appendingPathComponent("catalog.json"))) as! [String:Any]
let characters=catalog["characters"] as! [[String:Any]]
var allBounds=[[[Int]]]()
var header="#pragma once\n#include <stdint.h>\nstatic constexpr int PIXEL_SIZE=96;\nstatic const uint16_t PIXEL_PIPS[\(characters.count)][24][9216]={\n"
for spec in characters {
    let rig=spec["id"] as! Int,name=spec["name"] as! String
    func load(_ path:String)->(Int,Int,[UInt8]) {
        let source=CGImageSourceCreateWithURL(art.appendingPathComponent(path) as CFURL,nil)!
        let image=CGImageSourceCreateImageAtIndex(source,0,nil)!,w=image.width,h=image.height
        var rgba=[UInt8](repeating:0,count:w*h*4)
        rgba.withUnsafeMutableBytes {bytes in
            let c=CGContext(data:bytes.baseAddress,width:w,height:h,bitsPerComponent:8,bytesPerRow:w*4,space:CGColorSpaceCreateDeviceRGB(),bitmapInfo:CGImageAlphaInfo.premultipliedLast.rawValue)!
            c.draw(image,in:CGRect(x:0,y:0,width:w,height:h))
        };return (w,h,rgba)
    }
    let base=load(spec["source"] as! String),extra=load(spec["expressionsSource"] as! String)
    var boxes=[CGRect]()
    for f in 0..<24 {
        let (w,h,rgba)=f<16 ? base:extra
        let cols=f<16 ? 4:8,rows=f<16 ? 4:(spec["expressionRows"] as! Int),col=f<16 ? f%4:f-16,row=f<16 ? f/4:(spec["expressionRow"] as! Int)
        let x0=col*w/cols,x1=(col+1)*w/cols,y0=row*h/rows,y1=(row+1)*h/rows
        var l=x1,r=x0,t=y1,b=y0
        for y in y0..<y1 {for x in x0..<x1 {if rgba[(y*w+x)*4+3]>=180 {l=min(l,x);r=max(r,x+1);t=min(t,y);b=max(b,y+1)}}}
        precondition(r>l && b>t,"Empty atlas cell")
        boxes.append(CGRect(x:l,y:t,width:r-l,height:b-t))
    }
    let baseScale=min(82/boxes.prefix(16).map(\.height).max()!,84/boxes.prefix(16).map(\.width).max()!)
    let extraScale=min(82/boxes.suffix(8).map(\.height).max()!,84/boxes.suffix(8).map(\.width).max()!)
    var rigBounds=[[Int]]()
    header+="{\n"
    for f in 0..<24 {
        let (w,h,rgba)=f<16 ? base:extra
        let scale=f<16 ? baseScale:extraScale
        let box=boxes[f],fw=Int((box.width*scale).rounded()),fh=Int((box.height*scale).rounded())
        let dx=(96-fw)/2,dy=90-fh-(f==9 ? 3:0)
        rigBounds.append([dx,dy,dx+fw,dy+fh])
        var output=[UInt8](repeating:0,count:96*96*4),encoded=[String]()
        for y in 0..<96 {for x in 0..<96 {
            var value:UInt16=0
            if x>=dx && x<dx+fw && y>=dy && y<dy+fh {
                let sx=min(w-1,Int(box.minX+Double(x-dx)/scale)),sy=min(h-1,Int(box.minY+Double(y-dy)/scale))
                let i=(sy*w+sx)*4,a=Int(rgba[i+3])
                if a>=180 {
                    let r=min(255,Int(rgba[i])*255/a),g=min(255,Int(rgba[i+1])*255/a),b=min(255,Int(rgba[i+2])*255/a),o=(y*96+x)*4
                    output[o]=UInt8(r);output[o+1]=UInt8(g);output[o+2]=UInt8(b);output[o+3]=255
                    value=UInt16((r>>3)<<11 | (g>>2)<<5 | b>>3);if value==0 {value=1}
                }
            }
            encoded.append(String(value))
        }}
        header+="{"+encoded.joined(separator:",")+"},\n"
        let data=Data(output),provider=CGDataProvider(data:data as CFData)!
        let cg=CGImage(width:96,height:96,bitsPerComponent:8,bitsPerPixel:32,bytesPerRow:384,space:CGColorSpaceCreateDeviceRGB(),bitmapInfo:CGBitmapInfo(rawValue:CGImageAlphaInfo.last.rawValue),provider:provider,decode:nil,shouldInterpolate:false,intent:.defaultIntent)!
        let asset=root.appendingPathComponent("ios/Piko/Piko/Assets.xcassets/Pixel\(rig)_\(f).imageset")
        try fm.createDirectory(at:asset,withIntermediateDirectories:true)
        let dest=CGImageDestinationCreateWithURL(asset.appendingPathComponent("frame.png") as CFURL,"public.png" as CFString,1,nil)!
        CGImageDestinationAddImage(dest,cg,nil);precondition(CGImageDestinationFinalize(dest))
        try Data("{\"images\":[{\"idiom\":\"universal\",\"filename\":\"frame.png\"}],\"info\":{\"author\":\"xcode\",\"version\":1}}".utf8).write(to:asset.appendingPathComponent("Contents.json"))
        let web=root.appendingPathComponent("server/sim/pixel-\(rig)-\(f).png")
        if fm.fileExists(atPath:web.path){try fm.removeItem(at:web)}
        try fm.copyItem(at:asset.appendingPathComponent("frame.png"),to:web)
    }
    header+="},\n"
    allBounds.append(rigBounds)
    print("Registered \(name): 24 frames, 96×96")
}
header+="};\n"
header+="static const uint8_t PIXEL_BOUNDS[\(characters.count)][24][4]={"+allBounds.map{rig in "{"+rig.map{"{"+$0.map(String.init).joined(separator:",")+"}"}.joined(separator:",")+"}"}.joined(separator:",")+"};\n"
try header.write(to:root.appendingPathComponent("firmware/src/face/pixel_art.gen.h"),atomically:true,encoding:.utf8)
